const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/budget_views/%7Bbudget_view_id%7D/summary_rows',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'biller[]': 'SOME_ARRAY_VALUE',
    'cost_code_id[]': 'SOME_ARRAY_VALUE',
    'cost_code_name[]': 'SOME_ARRAY_VALUE',
    'root_cost_code_id[]': 'SOME_ARRAY_VALUE',
    'root_cost_code_name[]': 'SOME_ARRAY_VALUE',
    'category_id[]': 'SOME_ARRAY_VALUE',
    'budget_line_item_id[]': 'SOME_ARRAY_VALUE',
    group_by: 'SOME_STRING_VALUE',
    budget_row_type: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/budget_views/%7Bbudget_view_id%7D/summary_rows?project_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&biller%5B%5D=SOME_ARRAY_VALUE&cost_code_id%5B%5D=SOME_ARRAY_VALUE&cost_code_name%5B%5D=SOME_ARRAY_VALUE&root_cost_code_id%5B%5D=SOME_ARRAY_VALUE&root_cost_code_name%5B%5D=SOME_ARRAY_VALUE&category_id%5B%5D=SOME_ARRAY_VALUE&budget_line_item_id%5B%5D=SOME_ARRAY_VALUE&group_by=SOME_STRING_VALUE&budget_row_type=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
